{
  "findings": [
    {
      "ref": "[D537]",
      "area": "contact",
      "claim": "The default setting blocks text chat, voice chat, and video chat for Sub Accounts.",
      "stance": "mitigation",
      "quote": "The default setting is \"Block\" meaning chat/message is restricted."
    },
    {
      "ref": "[D537]",
      "area": "contact",
      "claim": "Even when chat is blocked, a Sub Account can still send predetermined text messages and see other users' in-game character names and designs.",
      "stance": "risk",
      "quote": "when this control is set to block, a Sub Account can still A) send and receive predetermined text messages created by a game or app, B) create and see other users' in-game character names, designs, and clan titles"
    },
    {
      "ref": "[D537]",
      "area": "contact",
      "claim": "A Sub Account can still communicate via third-party non-game apps even if chat/message is blocked on the system.",
      "stance": "risk",
      "quote": "communicate via third party, non-game apps"
    },
    {
      "ref": "[D537]",
      "area": "money",
      "claim": "A Master Account holder can set a monthly spending limit for a Sub Account, with the default set to $0.00 preventing any purchases.",
      "stance": "mitigation",
      "quote": "With this setting, a Master Account holder can set a monthly limit spending limit for a Sub Account to spend per month if the Master Account wallet has sufficient funds."
    },
    {
      "ref": "[D537]",
      "area": "money",
      "claim": "If the monthly spending limit restriction is removed, a Sub Account can buy and play any content including content not intended for their age.",
      "stance": "risk",
      "quote": "If this restriction is removed, a Sub Accounts will be able to buy and play any content, including content that is not intended for his/her age or may be inappropriate according to the ESRB rating system."
    },
    {
      "ref": "[D537]",
      "area": "data",
      "claim": "The text does not describe what data the app collects, whether it tracks for ads, or if data can be deleted.",
      "stance": "neutral",
      "quote": "N/A"
    },
    {
      "ref": "[D537]",
      "area": "age_gating",
      "claim": "The PS4 system honors Chat/Message and User Generated Media controls separately from the Sub Account's age-based content restrictions.",
      "stance": "neutral",
      "quote": "Although PSN parental control settings control an account's activities throughout PSN, they restrict content in different ways on different PlayStation systems. The PS4 system honors Chat/Message and User Generated Media (\"UGM\") controls (described below) separately."
    },
    {
      "ref": "[D537]",
      "area": "age_gating",
      "claim": "A parent can set the PS4 system's parental control level lower than the game's level to restrict access, with the default set to level 9.",
      "stance": "mitigation",
      "quote": "The combination of the parental control level you set for each child on your PS4™ system and the parental control level for the game limits what games can be played. For example, if you want to restrict use of a game with a parental control level of \"4\", set your PS4 system's parental control level one number lower to \"3\"."
    },
    {
      "ref": "[D537]",
      "area": "content",
      "claim": "The default setting restricts content based on the ESRB rating system, preventing a Sub Account from buying or playing software not intended for their age.",
      "stance": "mitigation",
      "quote": "This setting allows a Master Account holder to A) prevent a Sub Account from buying game content through PSN that not intended for his/her age according to the ESRB rating system and B) prevent a Sub Account from playing software content on PSN that is not intended for his age according to the ESRB rating system. The default value is set to \"On\" meaning content will be restricted based on user age."
    },
    {
      "ref": "[D537]",
      "area": "developer_record",
      "claim": "The text does not mention any fines, breaches, lawsuits, or regulatory actions involving the developer.",
      "stance": "neutral",
      "quote": "N/A"
    }
  ]
}
